pm.test('HTTP 201 Created - Tạo voucher tiền mặt thành công', function () {
    pm.response.to.have.status(201);
});
var data = pm.response.json();
pm.test('Kiểm tra loại FIXED_AMOUNT và discountValue', function () {
    pm.expect(data.discountType).to.eql('FIXED_AMOUNT');
    pm.expect(Number(data.discountValue)).to.eql(50000);
});

pm.test('HTTP 200 OK - Áp dụng voucher tiền mặt thành công', function () {
    pm.response.to.have.status(200);
});
var data = pm.response.json();
pm.test('Giảm đúng 50.000 đ', function () {
    pm.expect(Number(data.discountAmount)).to.eql(50000);
    pm.expect(Number(data.finalAmount)).to.eql(150000);
});
